import pandas as pd
import numpy as np

# Get mean expression of key markers across clusters
markers = ['CD74', 'HLA-A', 'HLA-DMA', 'B2M', 'CD3D', 'CD3E', 'CD4', 'CD14', 'CD68', 'FCGR3A', 'NKG7', 'GNLY', 'KLRD1', 'CD86', 'ITGAX']
clusters = ['3', '12', '18', '0']

marker_data = {}
for cluster in clusters:
    cell_mask = adata.obs['leiden'] == cluster
    for gene in markers:
        if gene in adata.var_names:
            gene_idx = adata.var_names == gene
            expr = adata[cell_mask].X[:, gene_idx]
            if hasattr(expr, 'A'):
                mean_exp = np.mean(expr.A)
            else:
                mean_exp = np.mean(expr)
            marker_data[f'{cluster} {gene}'] = mean_exp

# Create a nice table
df = pd.DataFrame(marker_data).T
df.index.name = 'Cluster'
print("=== Marker expression by cluster ===")
print(df.round(4))

# Also check for T cell markers
print("\n=== T cell marker check ===")
t_cell_markers = ['CD3D', 'CD3E', 'CD4', 'CD8A', 'TRAC', 'TRBC']
